function rangeAlternatives(a, b) {
  // a,b equal length strings, a <= b lexicographically; digits only
  if (a === b) return [a];
  const n = a.length;
  // common prefix
  let p = 0;
  while (p < n && a[p] === b[p]) p++;
  if (p > 0) {
    const prefix = a.slice(0, p);
    const rest = rangeAlternatives(a.slice(p), b.slice(p));
    return rest.map(r => prefix + r);  // prefix has no alternation, fine
  }
  // a[0] < b[0]
  const lo = +a[0], hi = +b[0];
  if (n === 1) {
    return [charClass(lo, hi)];
