  const out = [];
  const tailAny = anyDigits(n - 1);
  // low branch
  const lowRest = rangeAlternatives(a.slice(1), '9'.repeat(n - 1));
  out.push(...lowRest.map(r => a[0] + r));
  // middle
  if (hi - lo > 1) {
    out.push(`[${lo + 1}-${hi - 1}]` + tailAny);
  }
  // high branch
  const highRest = rangeAlternatives('0'.repeat(n - 1), b.slice(1));
  out.push(...highRest.map(r => b[0] + r));
