```js
const MAX_SAFE = ...

function charClass(lo, hi) {
  if (lo === hi) return String(lo);
  return `[${lo}-${hi}]`;
}

function anyDigits(count) {
  if (count === 0) return "";
  if (count === 1) return "[0-9]";
  return `[0-9]{${count}}`;
}

function toAlternatives(low, high) {
  if (low === high) return [low];
  const n = low.length;
  let shared = 0;
  while (shared < n && low[shared] === high[shared]) shared += 1;
  if (shared > 0) {
    const prefix = low.slice(0, shared);
    return toAlternatives(low.slice(shared), high.slice(shared)).map(
      (alt) => prefix + alt,
    );
  }
  const first = Number(low[0]);
  const last = Number(high[0]);
  if (n === 1) return [charClass(first, last)];
  const rest = anyDigits(n - 1);
  const alternatives = [];
  for (const alt of toAlternatives(low.slice(1), "9".repeat(n - 1))) {
    alternatives.push(low[0] + alt);
  }
  if (last - first > 1) {
    alternatives.push(`[${first + 1}-${last - 1}]${rest}`);
  }
  for (const alt of toAlternatives("0".repeat(n - 1), high.slice(1))) {
    alternatives.push(high[0] + alt);
  }
  return alternatives;
}

function group(alternatives) {
  if (alternatives.length === 1) return alternatives[0];
  return `(?:${alternatives.join("|")})`;
}

export function rangeToRegex(min, max, options = {}) {
  const { anchors = true } = options;
  min = BigInt(min);
  max = BigInt(max);
  if (min < 0n) throw new RangeError("rangeToRegex only supports non-negative ranges");
  if (min > max) throw new RangeError(`invalid range: ${min} > ${max}`);
  const minDigits = min.toString().length;
  const maxDigits = max.toString().length;
  const branches = [];
  for (let digits = minDigits; digits <= maxDigits; digits += 1) {
    const lower = digits === 1 ? 0n : 10n ** BigInt(digits - 1);
    const upper = 10n ** BigInt(digits) - 1n;
    const low = min > lower ? min : lower;
    const high = max < upper ? max : upper;
    if (low > high) continue;
    branches.push(group(toAlternatives(low.toString(), high.toString())));
  }
  const body = branches.join("|");
  const pattern = branches.length === 1 ? body : `(?:${body})`;
  return anchors ? `^(?:${body})$` : body;
}
```

