{
  "name": "range-to-regex",
  "version": "1.0.0",
  "description": "Convert a numeric range such as 1-100 into a single regular expression that matches any number in that range.",
  "type": "module",
  "main": "src/range-to-regex.js",
  "exports": {
    ".": "./src/range-to-regex.js"
  },
  "bin": {
    "range-to-regex": "./bin/range-to-regex.js"
  },
  "scripts": {
    "start": "node bin/range-to-regex.js",
    "test": "node --test"
  },
  "engines": {
    "node": ">=18"
  },
  "license": "MIT"
}

function charClass(low, high) {
  return low === high ? String(low) : `[${low}-${high}]`;
}

function anyDigits(count) {
  if (count === 0) return "";
  return count === 1 ? "[0-9]" : `[0-9]{${count}}`;
}

function group(alternatives) {
  return alternatives.length === 1
    ? alternatives[0]
    : `(?:${alternatives.join("|")})`;
}

function toAlternatives(low, high) {
  if (low === high) return [low];

  const length = low.length;
  let shared = 0;
  while (shared < length && low[shared] === high[shared]) shared += 1;

  if (shared > 0) {
    const prefix = low.slice(0, shared);
    return toAlternatives(low.slice(shared), high.slice(shared)).map(
      (alternative) => prefix + alternative,
    );
  }

  const first = Number(low[0]);
  const last = Number(high[0]);

  if (length === 1) return [charClass(first, last)];

  const tail = anyDigits(length - 1);
  const alternatives = [];

  for (const rest of toAlternatives(low.slice(1), "9".repeat(length - 1))) {
    alternatives.push(low[0] + rest);
  }

  if (last - first > 1) {
    alternatives.push(`[${first + 1}-${last - 1}]${tail}`);
  }

  for (const rest of toAlternatives("0".repeat(length - 1), high.slice(1))) {
    alternatives.push(high[0] + rest);
  }

  return alternatives;
}

export function parseRange(input) {
  const match = /^\s*(\d+)\s*-\s*(\d+)\s*$/.exec(String(input));
  if (!match) {
    throw new RangeError(
      `expected a range like "1-100", received "${input}"`,
    );
  }
  return [match[1], match[2]];
}

export function rangeToRegex(min, max, options = {}) {
  const { anchors = true } = options;

  min = BigInt(min);
  max = BigInt(max);

  if (min < 0n) {
    throw new RangeError("rangeToRegex only supports non-negative ranges");
  }
  if (min > max) {
    throw new RangeError(`invalid range: ${min} is greater than ${max}`);
  }

  const firstDigits = min.toString().length;
  const lastDigits = max.toString().length;
  const branches = [];

  for (let digits = firstDigits; digits <= lastDigits; digits += 1) {
    const lower = digits === 1 ? 0n : 10n ** BigInt(digits - 1);
    const upper = 10n ** BigInt(digits) - 1n;
    const low = min > lower ? min : lower;
    const high = max < upper ? max : upper;

    if (low > high) continue;

    branches.push(group(toAlternatives(low.toString(), high.toString())));
  }

  const body = branches.join("|");
  return anchors ? `^(?:${body})$` : body;
}

export function rangeToRegexFromString(input, options) {
  return rangeToRegex(...parseRange(input), options);
}

#!/usr/bin/env node
import { rangeToRegexFromString } from "../src/range-to-regex.js";

const input = process.argv[2];

if (!input || input === "-h" || input === "--help") {
  console.log("Usage: range-to-regex <min>-<max>");
  console.log('Example: range-to-regex 1-100');
  process.exit(input ? 0 : 1);
}

try {
  console.log(rangeToRegexFromString(input));
} catch (error) {
  console.error(`error: ${error.message}`);
  process.exit(1);
}

import test from "node:test";
import assert from "node:assert/strict";
import {
  parseRange,
  rangeToRegex,
  rangeToRegexFromString,
} from "../src/range-to-regex.js";

const compile = (min, max) => new RegExp(rangeToRegex(min, max));
const accepts = (regex, value) => regex.test(String(value));

test("matches the canonical 1-100 example", () => {
  const regex = compile(1, 100);

  for (let value = 1; value <= 100; value += 1) {
    assert.equal(accepts(regex, value), true, `${value} should match`);
  }

  for (const value of ["0", "101", "1000", "007", "-5", "1a", ""]) {
    assert.equal(accepts(regex, value), false, `"${value}" should not match`);
  }
});

test("supports single value and single digit ranges", () => {
  const single = compile(42, 42);
  assert.equal(accepts(single, 42), true);
  assert.equal(accepts(single, 41), false);
  assert.equal(accepts(single, 421), false);

  const digits = compile(3, 8);
  for (let value = 0; value <= 20; value += 1) {
    assert.equal(accepts(digits, value), value >= 3 && value <= 8);
  }
});

test("brute-force verifies every sub-range in a small window", () => {
  for (let min = 0; min <= 25; min += 1) {
    for (let max = min; max <= 25; max += 1) {
      const regex = compile(min, max);
      const label = `range ${min}-${max}`;

      for (let value = 0; value <= 120; value += 1) {
        assert.equal(
          accepts(regex, value),
          value >= min && value <= max,
          `${label} with value ${value}`,
        );
      }
    }
  }
});

test("rejects leading zeros for multi-digit ranges", () => {
  const regex = compile(10, 999);
  for (const value of ["010", "099", "007"]) {
    assert.equal(accepts(regex, value), false, `"${value}" should not match`);
  }
});

test("handles ranges larger than Number.MAX_SAFE_INTEGER", () => {
  const regex = compile("9007199254740990", "9007199254740995");
  for (const value of [
    "9007199254740989",
    "9007199254740990",
    "9007199254740993",
    "9007199254740995",
    "9007199254740996",
  ]) {
    assert.equal(
      accepts(regex, value),
      value >= "9007199254740990" && value <= "9007199254740995",
      value,
    );
  }
});

test("anchoring can be disabled", () => {
  const regex = new RegExp(rangeToRegex(1, 100, { anchors: false }));
  assert.equal(regex.test("abc42xyz"), true);
  assert.equal(regex.test("abc999xyz"), false);
});

test("parseRange extracts bounds and rejects malformed input", () => {
  assert.deepEqual(parseRange("1-100"), ["1", "100"]);
  assert.deepEqual(parseRange(" 7 - 9 "), ["7", "9"]);
  assert.equal(rangeToRegexFromString("1-100"), rangeToRegex(1, 100));

  assert.throws(() => parseRange("abc"), RangeError);
  assert.throws(() => parseRange("100"), RangeError);
  assert.throws(() => rangeToRegex(10, 1), RangeError);
  assert.throws(() => rangeToRegex(-1, 5), RangeError);
});

